add_action('wp_footer', function () {
?>
<script>
(function () {

    'use strict';

    /*
     * ==========================================
     * CONFIG
     * ==========================================
     */

    const STORAGE_KEY =
        'pt_gtranslate_selected_lang';

    const DEFAULT_LANG =
        'en';

    const AJAX_URL =
        '<?php echo esc_url(admin_url('admin-ajax.php')); ?>';


    /*
     * ==========================================
     * SUPPORTED LANGUAGES
     * ==========================================
     */

    const supported = [
        'vi', 'en', 'ja', 'ko', 'zh', 'fr', 'de', 'es', 'it', 'pt',
        'ru', 'ar', 'th', 'id', 'ms', 'hi', 'nl', 'pl', 'tr',
        'cs', 'da', 'fi', 'el', 'he', 'hu', 'no', 'ro', 'sv', 'uk'
    ];


    /*
     * ==========================================
     * COUNTRY -> LANGUAGE
     * ==========================================
     */

    const countryLanguage = {

        'VN': 'vi',

        'KR': 'ko',

        'JP': 'ja',

        'CN': 'zh',
        'TW': 'zh',
        'HK': 'zh',
        'MO': 'zh',

        'TH': 'th',

        'ID': 'id',

        'MY': 'ms',

        'IN': 'hi',

        'FR': 'fr',

        'DE': 'de',
        'AT': 'de',
        'CH': 'de',

        'ES': 'es',

        'IT': 'it',

        'PT': 'pt',
        'BR': 'pt',

        'RU': 'ru',

        'NL': 'nl',

        'PL': 'pl',

        'TR': 'tr',

        'GR': 'el',

        'IL': 'he',

        'CZ': 'cs',

        'DK': 'da',

        'FI': 'fi',

        'HU': 'hu',

        'NO': 'no',

        'RO': 'ro',

        'SE': 'sv',

        'UA': 'uk',

        'SA': 'ar',
        'AE': 'ar',
        'QA': 'ar',
        'KW': 'ar',
        'BH': 'ar',
        'OM': 'ar',
        'JO': 'ar',
        'LB': 'ar',
        'EG': 'ar',
        'MA': 'ar',
        'DZ': 'ar',
        'TN': 'ar'

    };


    /*
     * ==========================================
     * GET GTRANSLATE COOKIE
     * ==========================================
     */

    function getGoogleLanguage() {

        const match =
            document.cookie.match(
                /(?:^|;\s*)googtrans=([^;]+)/
            );

        if (!match) {
            return null;
        }

        try {

            const value =
                decodeURIComponent(
                    match[1]
                );

            /*
             * /en/vi
             */

            const parts =
                value.split('/');

            if (parts.length >= 3) {

                const lang =
                    parts[2]
                        .toLowerCase();

                if (
                    supported.includes(lang)
                ) {
                    return lang;
                }
            }

        } catch (error) {

            console.log(
                '[GTranslate] Cookie error:',
                error
            );

        }

        return null;
    }


    /*
     * ==========================================
     * GET USER SELECTED LANGUAGE
     * ==========================================
     *
     * Nếu user đã chọn trước đó
     * thì luôn ưu tiên ngôn ngữ này.
     */

    function getUserSelectedLanguage() {

        try {

            const lang =
                localStorage.getItem(
                    STORAGE_KEY
                );

            if (
                lang &&
                supported.includes(lang)
            ) {
                return lang;
            }

        } catch (error) {

            console.log(
                '[GTranslate] LocalStorage error:',
                error
            );

        }

        return null;
    }


    /*
     * ==========================================
     * SAVE USER LANGUAGE
     * ==========================================
     */

    function saveUserLanguage(lang) {

        if (
            !lang ||
            !supported.includes(lang)
        ) {
            return;
        }

        try {

            localStorage.setItem(
                STORAGE_KEY,
                lang
            );

        } catch (error) {

            console.log(
                '[GTranslate] Cannot save language:',
                error
            );

        }
    }


    /*
     * ==========================================
     * SET GTRANSLATE COOKIE
     * ==========================================
     */

    function setGoogleLanguage(lang) {

        if (
            !lang ||
            !supported.includes(lang)
        ) {
            lang = DEFAULT_LANG;
        }

        const value =
            '/en/' + lang;


        document.cookie =
            'googtrans=' +
            encodeURIComponent(value) +
            '; path=/';


        /*
         * Domain cookie
         */

        try {

            document.cookie =
                'googtrans=' +
                encodeURIComponent(value) +
                '; path=/; domain=' +
                window.location.hostname;

        } catch (error) {

            // Ignore

        }
    }


    /*
     * ==========================================
     * COUNTRY -> LANGUAGE
     * ==========================================
     */

    function countryToLanguage(country) {

        country =
            String(country || '')
                .toUpperCase()
                .trim();


        if (
            countryLanguage[country]
        ) {

            return countryLanguage[country];

        }


        /*
         * Quốc gia không nằm trong mapping
         * => English
         */

        return DEFAULT_LANG;
    }


    /*
     * ==========================================
     * GET COUNTRY BY IP
     * ==========================================
     *
     * WordPress server sẽ gọi:
     *
     * https://ipwho.is/IP
     *
     * ==========================================
     */

    async function detectCountry() {

        try {

            const response =
                await fetch(
                    AJAX_URL +
                    '?action=pt_detect_country',
                    {
                        method: 'GET',

                        credentials:
                            'same-origin',

                        cache:
                            'no-store'
                    }
                );


            if (
                !response.ok
            ) {

                throw new Error(
                    'HTTP ' +
                    response.status
                );

            }


            const result =
                await response.json();


            if (
                !result ||
                !result.success ||
                !result.data
            ) {

                return null;

            }


            console.log(
                '[GTranslate] IP:',
                result.data.ip
            );


            console.log(
                '[GTranslate] Country:',
                result.data.country
            );


            return result.data.country;

        }

        catch (error) {

            console.error(
                '[GTranslate] Country detection error:',
                error
            );


            return null;

        }
    }


    /*
     * ==========================================
     * APPLY LANGUAGE
     * ==========================================
     */

    function applyLanguage(lang) {

        if (
            !lang ||
            !supported.includes(lang)
        ) {

            lang =
                DEFAULT_LANG;
        }


        const current =
            getGoogleLanguage();


        /*
         * Đã đúng ngôn ngữ
         * => không reload
         */

        if (
            current === lang
        ) {

            return;

        }


        console.log(
            '[GTranslate] Change:',
            current,
            '→',
            lang
        );


        setGoogleLanguage(
            lang
        );


        /*
         * Reload để GTranslate
         * áp dụng ngôn ngữ.
         */

        window.location.reload();

    }


    /*
     * ==========================================
     * WATCH GTRANSLATE SELECT
     * ==========================================
     *
     * Khi user chọn ngôn ngữ:
     *
     * Korean
     * Japanese
     * Vietnamese
     * ...
     *
     * => lưu lại.
     *
     * Lần sau IP không ghi đè.
     *
     * ==========================================
     */

    function watchGTranslate() {

        const select =
            document.querySelector(
                '.goog-te-combo'
            );


        if (!select) {

            return false;

        }


        if (
            select.dataset.ptLanguageWatch
        ) {

            return true;

        }


        select.dataset.ptLanguageWatch =
            '1';


        select.addEventListener(
            'change',
            function () {

                const lang =
                    String(
                        this.value || ''
                    )
                    .toLowerCase()
                    .trim();


                if (
                    !supported.includes(lang)
                ) {

                    return;

                }


                console.log(
                    '[GTranslate] USER SELECTED:',
                    lang
                );


                /*
                 * Lưu lựa chọn thật của user.
                 */

                saveUserLanguage(
                    lang
                );

            }
        );


        return true;

    }


    /*
     * ==========================================
     * WAIT GTRANSLATE
     * ==========================================
     */

    function waitForGTranslate() {

        let attempts = 0;


        const timer =
            setInterval(
                function () {

                    attempts++;


                    if (
                        watchGTranslate() ||
                        attempts >= 30
                    ) {

                        clearInterval(
                            timer
                        );

                    }

                },
                500
            );

    }


    /*
     * ==========================================
     * INITIALIZE
     * ==========================================
     */

    async function initialize() {

        /*
         * ======================================
         * PRIORITY 1
         *
         * USER ĐÃ CHỌN
         * ======================================
         */

        const userLanguage =
            getUserSelectedLanguage();


        if (userLanguage) {

            console.log(
                '[GTranslate] User language:',
                userLanguage
            );


            applyLanguage(
                userLanguage
            );


            return;

        }


        /*
         * ======================================
         * PRIORITY 2
         *
         * IP COUNTRY
         * ======================================
         */

        const country =
            await detectCountry();


        if (!country) {

            console.log(
                '[GTranslate] Cannot detect country.'
            );


            /*
             * Không xác định được IP
             * => English
             */

            applyLanguage(
                'en'
            );


            return;

        }


        /*
         * Country -> Language
         */

        const language =
            countryToLanguage(
                country
            );


        console.log(
            '[GTranslate] Country:',
            country
        );


        console.log(
            '[GTranslate] Language:',
            language
        );


        /*
         * Apply
         */

        applyLanguage(
            language
        );

    }


    /*
     * ==========================================
     * START
     * ==========================================
     */

    waitForGTranslate();


    /*
     * Đợi GTranslate load
     */

    setTimeout(
        function () {

            initialize();

        },
        700
    );


})();
</script>
<?php
});

add_action('rest_api_init', function () {

    register_rest_route('enishi/v1', '/livekit-token', [
        'methods' => 'GET',
        'permission_callback' => '__return_true',
        'callback' => function ($request) {

            $room = sanitize_text_field(
                $request->get_param('room')
            );

            $user = wp_get_current_user();

            return [
                'url' => 'wss://live.pt-solution.vn',
                'token' => enishi_generate_livekit_token(
                    $room,
                    (string)$user->ID
                )
            ];
        }
    ]);
});

function enishi_generate_livekit_token($room, $identity)
{
    $apiKey = 'ENISHI';
    $apiSecret = 'd8f8d3f9a2f4a3c8e7b1d5f6a9c2e4b7d1f8c3a6e9b2f5d7a4c1e8f6b3d9a2';

    $header = [
        'alg' => 'HS256',
        'typ' => 'JWT'
    ];

    $payload = [
        'iss' => $apiKey,
        'sub' => $identity,
        'nbf' => time(),
        'exp' => time() + 3600,
        'video' => [
            'roomJoin'     => true,
            'room'         => $room,
            'canPublish'   => true,
            'canSubscribe' => true
        ]
    ];

    $headerEncoded = rtrim(
        strtr(base64_encode(json_encode($header)), '+/', '-_'),
        '='
    );

    $payloadEncoded = rtrim(
        strtr(base64_encode(json_encode($payload)), '+/', '-_'),
        '='
    );

    $signature = hash_hmac(
        'sha256',
        $headerEncoded . '.' . $payloadEncoded,
        $apiSecret,
        true
    );

    $signatureEncoded = rtrim(
        strtr(base64_encode($signature), '+/', '-_'),
        '='
    );

    return $headerEncoded . '.' . $payloadEncoded . '.' . $signatureEncoded;
}
add_action('wp_ajax_get_user_photos', 'get_user_photos');

function get_user_photos()
{
    if (!is_user_logged_in()) {
        wp_send_json_error('Login required');
    }

    $user = wp_get_current_user();

    $upload_dir = wp_upload_dir();

    $folder_path = $upload_dir['basedir'] .
        '/place-media/' . $user->user_login;

    $folder_url = $upload_dir['baseurl'] .
        '/place-media/' . $user->user_login;

    $photos = [];

    if (is_dir($folder_path)) {

        $files = glob($folder_path . '/*.{jpg,jpeg,png,webp,gif,JPG,JPEG,PNG,WEBP,GIF}', GLOB_BRACE);

        foreach ($files as $file) {

            $photos[] = [
                'name' => basename($file),
                'url'  => $folder_url . '/' . basename($file)
            ];
        }
    }

    wp_send_json_success($photos);
}

