/**
 * =========================================================
 * DETECT COUNTRY FROM IP
 * =========================================================
 */

add_action(
    'wp_ajax_pt_detect_country',
    'pt_detect_country'
);

add_action(
    'wp_ajax_nopriv_pt_detect_country',
    'pt_detect_country'
);


function pt_detect_country() {

    /*
     * ==========================================
     * GET CLIENT IP
     * ==========================================
     */

    $ip = '';


    /*
     * Cloudflare
     */

    if (
        !empty(
            $_SERVER['HTTP_CF_CONNECTING_IP']
        )
    ) {

        $ip =
            sanitize_text_field(
                wp_unslash(
                    $_SERVER['HTTP_CF_CONNECTING_IP']
                )
            );

    }


    /*
     * Normal server
     */

    elseif (
        !empty(
            $_SERVER['REMOTE_ADDR']
        )
    ) {

        $ip =
            sanitize_text_field(
                wp_unslash(
                    $_SERVER['REMOTE_ADDR']
                )
            );

    }


    /*
     * ==========================================
     * CLOUDflare COUNTRY
     * ==========================================
     *
     * Nếu Cloudflare đã cung cấp country
     * thì không cần gọi IP API.
     */

    if (
        !empty(
            $_SERVER['HTTP_CF_IPCOUNTRY']
        )
    ) {

        $country =
            strtoupper(
                sanitize_text_field(
                    wp_unslash(
                        $_SERVER['HTTP_CF_IPCOUNTRY']
                    )
                )
            );


        if (
            preg_match(
                '/^[A-Z]{2}$/',
                $country
            )
        ) {

            wp_send_json_success([
                'ip'      => $ip,
                'country' => $country
            ]);

        }

    }


    /*
     * ==========================================
     * CHECK IP
     * ==========================================
     */

    if (
        empty($ip) ||
        !filter_var(
            $ip,
            FILTER_VALIDATE_IP
        )
    ) {

        /*
         * Development localhost / private IP
         *
         * Không trả HTTP 400.
         */

        wp_send_json_success([
            'ip'      => $ip,
            'country' => 'VN'
        ]);

    }


    /*
     * ==========================================
     * IPWHO.IS
     * ==========================================
     */

    $response =
        wp_remote_get(
            'https://ipwho.is/' .
            rawurlencode($ip),
            [
                'timeout' => 8,

                'headers' => [
                    'Accept' =>
                        'application/json'
                ]
            ]
        );


    /*
     * ==========================================
     * API ERROR
     * ==========================================
     */

    if (
        is_wp_error($response)
    ) {

        /*
         * Không trả HTTP 400.
         *
         * Trả English để website
         * vẫn hoạt động bình thường.
         */

        wp_send_json_success([
            'ip'      => $ip,
            'country' => 'US'
        ]);

    }


    /*
     * ==========================================
     * HTTP STATUS
     * ==========================================
     */

    $status =
        wp_remote_retrieve_response_code(
            $response
        );


    if (
        $status < 200 ||
        $status >= 300
    ) {

        wp_send_json_success([
            'ip'      => $ip,
            'country' => 'US'
        ]);

    }


    /*
     * ==========================================
     * PARSE JSON
     * ==========================================
     */

    $body =
        wp_remote_retrieve_body(
            $response
        );


    $data =
        json_decode(
            $body,
            true
        );


    /*
     * ==========================================
     * CHECK API RESPONSE
     * ==========================================
     */

    if (
        !is_array($data) ||
        empty($data['success'])
    ) {

        wp_send_json_success([
            'ip'      => $ip,
            'country' => 'US'
        ]);

    }


    /*
     * ==========================================
     * COUNTRY
     * ==========================================
     */

    $country =
        !empty(
            $data['country_code']
        )
            ? strtoupper(
                sanitize_text_field(
                    $data['country_code']
                )
            )
            : '';


    /*
     * ==========================================
     * COUNTRY INVALID
     * ==========================================
     */

    if (
        !preg_match(
            '/^[A-Z]{2}$/',
            $country
        )
    ) {

        $country = 'US';

    }


    /*
     * ==========================================
     * RETURN
     * ==========================================
     */

    wp_send_json_success([
        'ip'      => $ip,
        'country' => $country
    ]);

}

/* UPLOAD VIDEO */
function upload_place_video()
{
    if (!is_user_logged_in()) {
        wp_send_json_error(
            'You must be logged in.',
            403
        );
    }

    $place_id = isset($_POST['place_id'])
        ? sanitize_text_field(
            wp_unslash($_POST['place_id'])
        )
        : '';

    if (empty($place_id)) {
        wp_send_json_error(
            'Missing place ID.',
            400
        );
    }

    if (empty($_FILES['video'])) {
        wp_send_json_error(
            'No video selected.',
            400
        );
    }

    $file = $_FILES['video'];

    // Chỉ cho phép video
    if (strpos($file['type'], 'video/') !== 0) {
        wp_send_json_error(
            'Invalid video file.',
            400
        );
    }

    require_once ABSPATH . 'wp-admin/includes/file.php';
    require_once ABSPATH . 'wp-admin/includes/media.php';
    require_once ABSPATH . 'wp-admin/includes/image.php';

    // Upload Media Library
    $attachment_id = media_handle_upload(
        'video',
        0
    );

    if (is_wp_error($attachment_id)) {
        wp_send_json_error(
            $attachment_id->get_error_message(),
            500
        );
    }

    // Lưu Google Place ID
    update_post_meta(
        $attachment_id,
        'place_id',
        $place_id
    );

    wp_send_json_success([
        'id' => $attachment_id,
        'url' => wp_get_attachment_url(
            $attachment_id
        ),
        'mime_type' => get_post_mime_type(
            $attachment_id
        )
    ]);
}

add_action(
    'wp_ajax_upload_place_video',
    'upload_place_video'
);